      EPIC_DEPLOYMENT_ID: ${EPIC_DEPLOYMENT_ID:-}
      EPIC_CLIENT_ID: ${EPIC_CLIENT_ID:-}
      EPIC_CLIENT_SECRET: ${EPIC_CLIENT_SECRET:-}
      SFX_PACK_DIR: /app/sfx-runtime/audio/sfx
      PARSE_CAPTURE: ${PARSE_CAPTURE:-}
      PARSE_INGEST_URL: ${PARSE_INGEST_URL:-}
      PARSE_INGEST_TOKEN: ${PARSE_INGEST_TOKEN:-}
      PARSE_CAPTURE_SURFACES: ${PARSE_CAPTURE_SURFACES:-}
      PARSE_SPOOL_DIR: ${PARSE_SPOOL_DIR:-/app/parse-spool}
      PARSE_SPOOL_MAX_MB: ${PARSE_SPOOL_MAX_MB:-}
      PARSE_ENV_LABEL: ${PARSE_ENV_LABEL:-}
      PARSE_CENSUS: ${PARSE_CENSUS:-}
      PARSE_CENSUS_HOUR: ${PARSE_CENSUS_HOUR:-}
      WOC_BUILD_VERSION: ${WOC_BUILD_VERSION:-}
    ports:
    - 127.0.0.1:8787:8787
    volumes:
    - ${EASTBROOK_MEDIA_DIR:-./media-cache}:/app/dist/media
    - ${EASTBROOK_SFX_DIR:-./sfx-runtime}:/app/sfx-runtime:ro
    - ${PARSE_SPOOL_HOST_DIR:-./parse-spool}:/app/parse-spool
    extra_hosts:
    - host.docker.internal:host-gateway
    healthcheck:
      test:
      - CMD
      - node
      - -e
      - require('http').get('http://127.0.0.1:8787/livez',(r)=>process.exit(r.statusCode===200?0:1)).on('error',()=>process.exit(1))
      interval: 15s
      timeout: 5s
      retries: 4
      start_period: 60s
    stop_grace_period: 75s
    mem_limit: 5g
    memswap_limit: 5g
  discord-bot:
    image: eastbrook-game:${EASTBROOK_IMAGE_TAG:-local}
    container_name: eastbrook-discord-bot
    profiles:
    - discord
    restart: unless-stopped
    depends_on:
      game:
        condition: service_started
    environment:
      GAME_SERVER_URL: http://game:8787
      PUBLIC_GAME_URL: ${PUBLIC_GAME_URL:-http://localhost:8787}
      DISCORD_BOT_TOKEN: ${DISCORD_BOT_TOKEN:-}
      DISCORD_CLIENT_ID: ${DISCORD_CLIENT_ID:-}
      DISCORD_GUILD_ID: ${DISCORD_GUILD_ID:-}
      DISCORD_BOT_SECRET: ${DISCORD_BOT_SECRET:-}
      DISCORD_VOICE_CHANNEL_ID: ${DISCORD_VOICE_CHANNEL_ID:-}
      DISCORD_WELCOME_CHANNEL_ID: ${DISCORD_WELCOME_CHANNEL_ID:-}
      DISCORD_TEST_CHANNEL_ID: ${DISCORD_TEST_CHANNEL_ID:-}
      DISCORD_RELAY_CHANNEL_ID: ${DISCORD_RELAY_CHANNEL_ID:-}
      DISCORD_ACTIVITY_CHANNEL_ID: ${DISCORD_ACTIVITY_CHANNEL_ID:-}
      DISCORD_DAILY_REWARDS_CHANNEL_ID: ${DISCORD_DAILY_REWARDS_CHANNEL_ID:-}
      DISCORD_SYNC_NICKNAMES: ${DISCORD_SYNC_NICKNAMES:-1}
      DISCORD_MAX_RPS: ${DISCORD_MAX_RPS:-}
      DISCORD_BAN_PAUSE_MS: ${DISCORD_BAN_PAUSE_MS:-}
      DISCORD_BREAKER_LIMIT: ${DISCORD_BREAKER_LIMIT:-}
      DISCORD_FORBIDDEN_TTL_MS: ${DISCORD_FORBIDDEN_TTL_MS:-}
      DISCORD_ROLE_SYNC_INTERVAL_MS: ${DISCORD_ROLE_SYNC_INTERVAL_MS:-}
      DISCORD_PRESENCE_DEBOUNCE_MS: ${DISCORD_PRESENCE_DEBOUNCE_MS:-}
      DISCORD_SWEEP_SLICE_MS: ${DISCORD_SWEEP_SLICE_MS:-}
      DISCORD_SWEEP_SLICE_SIZE: ${DISCORD_SWEEP_SLICE_SIZE:-}
      DISCORD_OUTBOX_POLL_MS: ${DISCORD_OUTBOX_POLL_MS:-}
      DISCORD_OUTBOX_IDLE_MS: ${DISCORD_OUTBOX_IDLE_MS:-}
      DISCORD_OUTBOX_TIMEOUT_MS: ${DISCORD_OUTBOX_TIMEOUT_MS:-}
      DISCORD_HEARTBEAT_FILE: ${DISCORD_HEARTBEAT_FILE:-}
      DISCORD_HEARTBEAT_INTERVAL_MS: ${DISCORD_HEARTBEAT_INTERVAL_MS:-}
      DISCORD_HEARTBEAT_STALE_MS: ${DISCORD_HEARTBEAT_STALE_MS:-}
    command:
    - node
    - dist-bot/bot.cjs
    healthcheck:
      test:
      - CMD
      - node
      - -e
      - const fs=require('fs');const p=(process.env.DISCORD_HEARTBEAT_FILE||'').trim()||'/tmp/discord-bot-heartbeat';const
        s=Number(process.env.DISCORD_HEARTBEAT_STALE_MS);const stale=s>0?s:90000;try{process.exit(Date.now()-fs.statSync(p).mtimeMs<stale?0:1)}catch{process.exit(1)}
      interval: 15s
      timeout: 5s
      retries: 4
      start_period: 60s
    stop_grace_period: 15s
    mem_limit: 512m
    memswap_limit: 512m
  mediawiki-db:
    image: mariadb:11
    container_name: eastbrook-wiki-db
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: ${MEDIAWIKI_DB_NAME:-mediawiki}
      MYSQL_USER: ${MEDIAWIKI_DB_USER:-mediawiki}
      MYSQL_PASSWORD: ${MEDIAWIKI_DB_PASSWORD:-mediawiki-change-me}
      MYSQL_RANDOM_ROOT_PASSWORD: 'yes'
    volumes:
    - eastbrook_wikidb:/var/lib/mysql
    healthcheck:
      test:
      - CMD-SHELL
      - mariadb-admin ping -h 127.0.0.1 -u${MEDIAWIKI_DB_USER:-mediawiki} -p${MEDIAWIKI_DB_PASSWORD:-mediawiki-change-me}
        --silent
      interval: 5s
      timeout: 3s
      retries: 20
  mediawiki:
    build:
      context: .
      dockerfile: mediawiki/Dockerfile
    container_name: eastbrook-wiki
    restart: unless-stopped
    depends_on:
      mediawiki-db:
        condition: service_healthy
    environment:
      MEDIAWIKI_DB_HOST: mediawiki-db
      MEDIAWIKI_DB_NAME: ${MEDIAWIKI_DB_NAME:-mediawiki}
      MEDIAWIKI_DB_USER: ${MEDIAWIKI_DB_USER:-mediawiki}
      MEDIAWIKI_DB_PASSWORD: ${MEDIAWIKI_DB_PASSWORD:-mediawiki-change-me}
      MEDIAWIKI_ADMIN_USER: ${MEDIAWIKI_ADMIN_USER:-WikiAdmin}
      MEDIAWIKI_ADMIN_PASS: ${MEDIAWIKI_ADMIN_PASS:-change-me-admin-password}
      MEDIAWIKI_SECRET_KEY: ${MEDIAWIKI_SECRET_KEY:-local-dev-change-me-world-of-claudecraft}
      MEDIAWIKI_UPGRADE_KEY: ${MEDIAWIKI_UPGRADE_KEY:-local-dev-upgrade-key}
      MEDIAWIKI_SERVER: ${MEDIAWIKI_SERVER:-http://localhost:8080}
    ports:
    - 127.0.0.1:8080:80
    volumes:
    - eastbrook_wiki_images:/var/www/html/images
volumes:
  eastbrook_pgdata: null
  eastbrook_wikidb: null
  eastbrook_wiki_images: null
